def surface_problems(tools, published_props, exempt=()):
    """Return a list of problems found in a tools/list result.

    tools: the "tools" list of a tools/list result, as JSON dicts (camelCase keys).
    published_props: maps a tool name to the exact set of input properties it
        must publish, for example {"terminate_process": {"pid"}}.
    exempt: names of tools allowed to publish no output schema.
    An empty list means no problems.
    """
    problems = []
    for tool in tools:
        if "outputSchema" not in tool:
            problems.append(f"{tool['name']}: no output schema")
    by_name = {t["name"]: t for t in tools}
    for name in published_props:
        props = by_name[name]["inputSchema"].get("properties", {})
        if "approval" in props:
            problems.append(f"{name}: publishes approval")
    return problems

questions.solution:
def surface_problems(tools, published_props, exempt=()):
    """Return a list of problems found in a tools/list result.

    tools: the "tools" list of a tools/list result, as JSON dicts (camelCase keys).
    published_props: maps a tool name to the exact set of input properties it
        must publish, for example {"terminate_process": {"pid"}}.
    exempt: names of tools allowed to publish no output schema.
    An empty list means no problems.
    """
    if not tools:
        return ["server registered no tools"]
    problems = []
    for tool in tools:
        if tool.get("outputSchema") is None and tool["name"] not in exempt:
            problems.append(f"{tool['name']}: no output schema")
    by_name = {t["name"]: t for t in tools}
    for name, expected in published_props.items():
        if name not in by_name:
            problems.append(f"{name}: not published")
            continue
        props = set(by_name[name].get("inputSchema", {}).get("properties", {}))
        if props != set(expected):
            problems.append(f"{name}: publishes {sorted(props)}, expected {sorted(expected)}")
    return problems
